// Loads and shapes the page's data once, outside any component. Everything under
// $data/toronto-turnout is generated by analysis/toronto_election_turnout/09_final_synthesis.ipynb
// (section 10, "Front-end export") -- re-run that notebook rather than editing the files.

import tracts from '$data/toronto-turnout/ct.geo.json';
import meta from '$data/toronto-turnout/meta.json';
import loadings from '$data/toronto-turnout/component_1_loadings.json';

export { tracts, meta };

/** One flat record per tract, for the charts. */
export const tractRows = tracts.features.map((f) => f.properties);

/**
 * Component 1 ingredients: every variable with VIP > 1, from the largest positive loading
 * (top) to the largest negative one (bottom), as the notebook wrote them.
 */
export const ingredientRows = loadings.variables;
export const ingredientMeta = { minVip: loadings.min_vip, nModelVariables: loadings.n_variables_in_model };

/** Explorer variables (all of the model's predictors), grouped for the dropdown. */
const variablesByGroup = (family) => meta.explorer_variables.filter((v) => v.group === family);
export const explorerGroups = meta.explorer_groups.map((g) => ({ ...g, variables: variablesByGroup(g.family) }));
export const explorerVariables = meta.explorer_variables;
